<?php if($a['status']==='accepted'):
$slots=[];if((int)$a['advance_minor']>0)$slots['advance']='Аванс';if($a['delivered']&&(int)$a['price_minor']>(int)$a['advance_minor'])$slots['balance']='Остаток после приёмки';if($a['next']&&$a['next']<=gmdate('Y-m-d'))$slots[$a['next']]='Обслуживание с '.$a['next'];
